CREATE TABLE "Admin" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Admin_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Admin_email_key" ON "Admin"("email");
CREATE TABLE "Project" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "titleAr" TEXT NOT NULL DEFAULT '', "slug" TEXT NOT NULL, "description" TEXT NOT NULL, "descriptionAr" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL, "tags" TEXT[] NOT NULL, "imageUrl" TEXT, "liveUrl" TEXT, "repoUrl" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false, "published" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug");
CREATE TABLE "Skill" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "level" INTEGER NOT NULL DEFAULT 75, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Skill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Experience" ("id" TEXT NOT NULL, "role" TEXT NOT NULL, "company" TEXT NOT NULL, "period" TEXT NOT NULL, "description" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Experience_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SiteSettings" ("id" TEXT NOT NULL DEFAULT 'main', "name" TEXT NOT NULL DEFAULT 'Mahdi', "bio" TEXT NOT NULL DEFAULT '', "bioAr" TEXT NOT NULL DEFAULT '', "location" TEXT NOT NULL DEFAULT '', "email" TEXT NOT NULL DEFAULT '', "socials" JSONB NOT NULL DEFAULT '{}', "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "subject" TEXT NOT NULL, "message" TEXT NOT NULL, "read" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ActivityLog" ("id" TEXT NOT NULL, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ActivityLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Visit" ("id" TEXT NOT NULL, "path" TEXT NOT NULL, "country" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Visit_pkey" PRIMARY KEY ("id"));
